        ('71111111-1111-4111-8111-111111111113'::uuid, 'Английский язык для КТА в магистратуру', 'kta-english', 'Грамматика, академическая лексика и чтение текстов в формате вступительного комплексного тестирования.', 'Английский язык', 'https://images.unsplash.com/photo-1513258496099-48168024aec0?auto=format&fit=crop&w=1100&q=80'),
        ('71111111-1111-4111-8111-111111111114'::uuid, 'Профильные дисциплины КТА', 'kta-profile', 'Как готовиться к профильным предметам: диагностика, теория, конспекты, практика и повторение ошибок.', 'Профильные дисциплины', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=1100&q=80'),
        ('71111111-1111-4111-8111-111111111115'::uuid, 'Поступление в магистратуру: КТА, баллы и стратегия', 'kta-admission-plan', 'Понятный маршрут поступления: регистрация, проходные баллы, расписание подготовки и контроль прогресса.', 'Поступление', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1100&q=80'),
        ('71111111-1111-4111-8111-111111111116'::uuid, 'КТА: тренировочные сессии и разбор ошибок', 'kta-practice-strategy', 'Система регулярной практики: пробные тесты, журнал ошибок, повторение сложных тем и подготовка к экзаменационному темпу.', 'Практика', 'https://images.unsplash.com/photo-1484480974693-6ca0a78fb36b?auto=format&fit=crop&w=1100&q=80')
)
insert into courses(id, title, slug, description, status, subject, cover_url, created_at, updated_at)
select id, title, slug, description, 'PUBLISHED', subject, cover_url, now(), now()
from course_seed
on conflict (slug) do update
set title = excluded.title,
    description = excluded.description,
    status = excluded.status,
    subject = excluded.subject,
    cover_url = excluded.cover_url,
    updated_at = now();

