insert into course_modules(id, course_id, title, order_number)
select module_seed.id, courses.id, module_seed.title, module_seed.order_number
from module_seed
join courses on courses.slug = module_seed.course_slug
where not exists (
    select 1
    from course_modules existing
    where existing.course_id = courses.id
      and existing.title = module_seed.title
);

with lesson_seed(id, course_slug, module_title, title, content, duration_minutes, order_number) as (
    values
        ('71311111-1111-4111-8111-111111111111'::uuid, 'kta-tgo', 'Формат ТГО', 'Структура ТГО в КТА', E'Цель урока: понять, из каких частей состоит тест на готовность к обучению и как распределять время.\n\nЧто сделать: выпиши блоки ТГО, отметь задания на критическое и аналитическое мышление, затем выбери порядок прохождения от простого к сложному.\n\nРезультат: ты знаешь, где быстро набрать уверенные баллы и где нельзя тратить лишние минуты.', 18, 1),
        ('71311111-1111-4111-8111-111111111112'::uuid, 'kta-tgo', 'Формат ТГО', 'Критическое мышление: как читать условие', E'Цель урока: научиться отделять факт, вывод и предположение.\n\nЧто сделать: читай условие два раза, подчеркивай опорные слова и проверяй каждый вариант ответа вопросом: следует ли это прямо из текста.\n\nРезультат: меньше ошибок из-за красивых, но неподтвержденных вариантов.', 22, 2),
        ('71311111-1111-4111-8111-111111111113'::uuid, 'kta-tgo', 'Формат ТГО', 'Аналитическое мышление: таблицы и связи', E'Цель урока: переводить текстовую задачу в таблицу, схему или короткую систему условий.\n\nЧто сделать: выпиши объекты, признаки и ограничения, затем заполняй только то, что следует из условия.\n\nРезультат: сложная задача становится набором маленьких проверяемых шагов.', 24, 3),
        ('71311111-1111-4111-8111-111111111114'::uuid, 'kta-tgo', 'Практика мышления', 'План решения задания за 90 секунд', E'Цель урока: уложиться в экзаменационный темп без паники.\n\nЧто сделать: 20 секунд на чтение, 40 секунд на решение, 20 секунд на проверку, 10 секунд на выбор ответа. Если прогресса нет, пометь вопрос и переходи дальше.\n\nРезультат: ты контролируешь время и не зависаешь на одном задании.', 16, 1),
        ('71311111-1111-4111-8111-111111111115'::uuid, 'kta-tgo', 'Практика мышления', 'Типовые ошибки в ТГО', E'Цель урока: увидеть повторяющиеся ловушки.\n\nЧто сделать: после каждой тренировки записывай ошибку в одну из групп: невнимательное чтение, лишнее предположение, неверная схема, ошибка счета, нехватка времени.\n\nРезультат: подготовка становится точной, потому что ты исправляешь причину, а не просто решаешь больше заданий.', 20, 2),
        ('71311111-1111-4111-8111-111111111116'::uuid, 'kta-tgo', 'Практика мышления', 'Мини-тренировка: выводы и допущения', E'Цель урока: закрепить критическое мышление на коротких упражнениях.\n\nЧто сделать: для каждого утверждения отметь, является ли оно фактом из условия, возможным выводом или лишним допущением. Правильный ответ должен опираться только на текст.\n\nРезультат: ты быстрее отсекаешь варианты, которые звучат правдоподобно, но не доказаны.', 20, 3),

        ('71311111-1111-4111-8111-111111111117'::uuid, 'kta-logika', 'Основы', 'Структура логического блока', E'Цель урока: понять основные типы логических заданий в подготовке к КТА.\n\nЧто сделать: раздели задания на последовательности, выводы, условия, таблицы и задачи на соответствие. Для каждого типа держи отдельный способ решения.\n\nРезультат: ты не решаешь все задания одним способом и быстрее выбираешь рабочий алгоритм.', 18, 1),
        ('71311111-1111-4111-8111-111111111118'::uuid, 'kta-logika', 'Основы', 'Числовые последовательности', E'Цель урока: находить закономерность без перебора всех вариантов.\n\nЧто сделать: проверь разность, множитель, чередование двух рядов, квадрат или куб числа, затем сравни правило на нескольких соседних элементах.\n\nРезультат: ответ выбирается по правилу, а не по догадке.', 24, 2),
        ('71311111-1111-4111-8111-111111111119'::uuid, 'kta-logika', 'Основы', 'Аргументы и выводы', E'Цель урока: отличать правильный вывод от похожего по смыслу варианта.\n\nЧто сделать: сократи условие до двух-трех посылок и проверь, добавляет ли вариант ответа новую информацию. Если добавляет, это не строгий вывод.\n\nРезультат: меньше ошибок в заданиях, где варианты специально похожи друг на друга.', 26, 3),
        ('71311111-1111-4111-8111-111111111120'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Диаграммы и множества', E'Цель урока: решать задачи, где объекты входят в несколько групп.\n\nЧто сделать: используй круги, таблицы или короткие обозначения. Сначала заполняй пересечения, затем только одиночные области.\n\nРезультат: условия не смешиваются, а количество вариантов становится управляемым.', 22, 1),
        ('71311111-1111-4111-8111-111111111121'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Условия с несколькими ограничениями', E'Цель урока: не терять ограничения в длинной задаче.\n\nЧто сделать: каждое условие запиши отдельной строкой, затем вычеркивай невозможные варианты. Не держи все связи в голове.\n\nРезультат: сложная логическая задача превращается в последовательное исключение лишнего.', 24, 2),
        ('71311111-1111-4111-8111-111111111122'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Проверка ответа без угадывания', E'Цель урока: быстро проверить выбранный вариант.\n\nЧто сделать: подставь ответ обратно в условие и проверь все ограничения, а не только последнее. Если одно условие ломается, ответ неверный.\n\nРезультат: ты находишь ошибки до отправки ответа.', 16, 3),

        ('71311111-1111-4111-8111-111111111123'::uuid, 'kta-english', 'Основы', 'Диагностика уровня', E'Цель урока: определить слабые темы до начала подготовки.\n\nЧто сделать: пройди короткий срез по грамматике, чтению и лексике, затем отметь темы, где ошибка повторяется два раза и чаще.\n\nРезультат: у тебя появляется личный список тем, а не абстрактная цель выучить английский.', 18, 1),
        ('71311111-1111-4111-8111-111111111124'::uuid, 'kta-english', 'Основы', 'Academic vocabulary', E'Цель урока: понимать академические слова по контексту.\n\nЧто сделать: учи не отдельные переводы, а связки слов: причина, следствие, сравнение, противопоставление, пример. В тексте ищи маркеры связи между предложениями.\n\nРезультат: незнакомое слово реже ломает понимание всего абзаца.', 22, 2),
        ('71311111-1111-4111-8111-111111111125'::uuid, 'kta-english', 'Основы', 'Reading strategies', E'Цель урока: читать текст быстрее и точнее.\n\nЧто сделать: сначала найди тему текста и позицию автора, затем переходи к вопросам на детали. Не переводи каждое слово, если смысл предложения уже понятен.\n\nРезультат: ты экономишь время на чтении и меньше путаешь похожие ответы.', 24, 3),
        ('71311111-1111-4111-8111-111111111126'::uuid, 'kta-english', 'Чтение и грамматика', 'Grammar focus: времена и модальные глаголы', E'Цель урока: закрыть частые грамматические ошибки.\n\nЧто сделать: для каждого предложения найди время, лицо, число и модальный оттенок. Только после этого выбирай форму глагола.\n\nРезультат: ответ становится логичным по грамматике, а не выбранным по звучанию.', 24, 1),
        ('71311111-1111-4111-8111-111111111127'::uuid, 'kta-english', 'Чтение и грамматика', 'Reading: main idea и details', E'Цель урока: различать вопросы на главную мысль и детали.\n\nЧто сделать: если вопрос про main idea, смотри на весь текст. Если вопрос про detail, найди конкретную строку и не обобщай лишнего.\n\nРезультат: ты не отвечаешь деталями на общий вопрос и наоборот.', 22, 2),
        ('71311111-1111-4111-8111-111111111128'::uuid, 'kta-english', 'Чтение и грамматика', 'Ошибки в вариантах ответа', E'Цель урока: видеть ловушки в английских тестах.\n\nЧто сделать: проверяй варианты на слишком широкое обобщение, противоположный смысл, слово из текста без правильной идеи и грамматически красивую, но неверную форму.\n\nРезультат: ты выбираешь ответ по смыслу текста, а не по знакомым словам.', 20, 3),

        ('71311111-1111-4111-8111-111111111129'::uuid, 'kta-profile', 'Основы', 'Диагностический разбор', E'Цель урока: начать профильную подготовку с реальной картины знаний.\n\nЧто сделать: выбери темы дисциплины, пройди стартовый срез и отметь каждую тему цветом: знаю, путаюсь, не знаю.\n\nРезультат: план подготовки строится по слабым местам, а не по случайному порядку.', 18, 1),
        ('71311111-1111-4111-8111-111111111130'::uuid, 'kta-profile', 'Основы', 'Работа с теорией', E'Цель урока: учить теорию так, чтобы она помогала решать тест.\n\nЧто сделать: после каждого определения запиши пример, контрпример и связь с соседней темой. Не оставляй теорию в виде списка фраз.\n\nРезультат: понятия легче вспоминаются в задании.', 22, 2),
        ('71311111-1111-4111-8111-111111111131'::uuid, 'kta-profile', 'Основы', 'Закрепление темы', E'Цель урока: превратить изученную тему в устойчивый навык.\n\nЧто сделать: реши 10-15 заданий по одной теме, проверь ошибки, затем через два дня вернись к тем же типам вопросов.\n\nРезультат: тема не забывается сразу после чтения конспекта.', 24, 3),
        ('71311111-1111-4111-8111-111111111132'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Как выбрать профильные дисциплины', E'Цель урока: не ошибиться с направлением подготовки.\n\nЧто сделать: сверь образовательную программу, группу направлений и перечень профильных дисциплин, затем собери список тем для каждой дисциплины.\n\nРезультат: ты готовишь именно те предметы, которые нужны для поступления.', 18, 1),
        ('71311111-1111-4111-8111-111111111133'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Конспект по темам кодификатора', E'Цель урока: сделать конспект рабочим инструментом.\n\nЧто сделать: на одну тему оставляй одну страницу: определения, формулы или правила, два примера и три частые ошибки.\n\nРезультат: перед тестом можно быстро повторить главное без перечитывания учебника.', 26, 2),
        ('71311111-1111-4111-8111-111111111134'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Практика по слабым темам', E'Цель урока: убрать повторяющиеся ошибки.\n\nЧто сделать: сортируй ошибки по теме и причине. Если ошибка повторяется, вернись к теории, а не просто решай новые задания.\n\nРезультат: балл растет за счет точечного исправления слабых мест.', 22, 3),

        ('71311111-1111-4111-8111-111111111135'::uuid, 'kta-admission-plan', 'Поступление', 'Что такое КТА для магистратуры', E'Цель урока: понять роль комплексного тестирования при поступлении.\n\nЧто сделать: разберись, какие блоки относятся к твоему направлению, какой порог нужен и какие документы понадобятся для регистрации.\n\nРезультат: подготовка становится привязанной к поступлению, а не просто к набору тестов.', 16, 1),
        ('71311111-1111-4111-8111-111111111136'::uuid, 'kta-admission-plan', 'Поступление', 'Баллы и приоритеты подготовки', E'Цель урока: распределить усилия по блокам теста.\n\nЧто сделать: выпиши максимальные баллы по каждому разделу и отметь, где проще всего поднять результат за ближайшие две недели.\n\nРезультат: ты не тратишь одинаковое время на темы с разной отдачей.', 18, 2),
        ('71311111-1111-4111-8111-111111111137'::uuid, 'kta-admission-plan', 'Поступление', 'Регистрация и дедлайны', E'Цель урока: не потерять поступление из-за организационных ошибок.\n\nЧто сделать: заведи календарь регистрации, оплаты при необходимости, выбора пункта тестирования, даты экзамена и подачи документов.\n\nРезультат: все важные шаги видны заранее.', 14, 3),
        ('71311111-1111-4111-8111-111111111138'::uuid, 'kta-admission-plan', 'План подготовки', 'План на 30 дней', E'Цель урока: собрать короткий интенсив без хаоса.\n\nЧто сделать: 5 дней диагностики и базовой теории, 15 дней практики по темам, 7 дней пробных тестов, 3 дня легкого повторения и сна.\n\nРезультат: у тебя есть реалистичный план до экзамена.', 18, 1),
        ('71311111-1111-4111-8111-111111111139'::uuid, 'kta-admission-plan', 'План подготовки', 'План на 90 дней', E'Цель урока: выстроить спокойную подготовку на три месяца.\n\nЧто сделать: первый месяц закрывает теорию, второй месяц усиливает практику, третий месяц имитирует экзамен и исправляет ошибки.\n\nРезультат: подготовка идет без перегруза и случайных рывков.', 18, 2),
        ('71311111-1111-4111-8111-111111111140'::uuid, 'kta-admission-plan', 'План подготовки', 'Контроль прогресса', E'Цель урока: измерять реальные изменения.\n\nЧто сделать: раз в неделю фиксируй балл, время, ошибки по темам и вопросы, где ты сомневался. Смотри не только на итоговый процент, но и на причины ошибок.\n\nРезультат: ты видишь, что именно улучшилось и что еще тормозит результат.', 20, 3),

        ('71311111-1111-4111-8111-111111111141'::uuid, 'kta-practice-strategy', 'Тренировки', 'Как проходить пробный тест', E'Цель урока: сделать пробный тест похожим на настоящий экзамен.\n\nЧто сделать: поставь таймер, убери подсказки, проходи все блоки подряд и не проверяй ответы до конца попытки.\n\nРезультат: итоговый балл показывает реальную готовность, а не комфортную домашнюю практику.', 16, 1),
        ('71311111-1111-4111-8111-111111111142'::uuid, 'kta-practice-strategy', 'Тренировки', 'Экзаменационный темп', E'Цель урока: научиться двигаться по тесту без потери времени.\n\nЧто сделать: на первой проходке решай легкие вопросы, на второй возвращайся к средним, на третьей оставляй только сложные.\n\nРезультат: легкие баллы не теряются из-за одной трудной задачи.', 18, 2),
        ('71311111-1111-4111-8111-111111111143'::uuid, 'kta-practice-strategy', 'Тренировки', 'Повторение перед экзаменом', E'Цель урока: повторить главное без перегрузки.\n\nЧто сделать: за последние дни смотри только конспект ошибок, формулы, правила и задания, где раньше были сомнения.\n\nРезультат: перед экзаменом ты укрепляешь известное, а не открываешь новые тяжелые темы.', 14, 3),
        ('71311111-1111-4111-8111-111111111144'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Журнал ошибок', E'Цель урока: хранить ошибки так, чтобы они приносили пользу.\n\nЧто сделать: для каждой ошибки записывай тему, тип задания, выбранный ответ, правильную идею и причину промаха.\n\nРезультат: журнал становится картой подготовки, а не списком неудач.', 18, 1),
        ('71311111-1111-4111-8111-111111111145'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Повтор сложных вопросов', E'Цель урока: возвращать сложные задания в правильный момент.\n\nЧто сделать: повторяй ошибочные вопросы через 1 день, 3 дня и 7 дней. Если снова ошибка, вернись к теории.\n\nРезультат: слабые темы закрепляются постепенно.', 16, 2),
        ('71311111-1111-4111-8111-111111111146'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Как понять, что тема закрыта', E'Цель урока: не обманывать себя ощущением знакомой темы.\n\nЧто сделать: тема считается закрытой, если ты решаешь новые задания правильно, укладываешься во время и можешь объяснить ход решения.\n\nРезультат: прогресс становится реальным и проверяемым.', 18, 3)
),
target_lessons as (
    select lesson_seed.*, course_modules.id as module_id
    from lesson_seed
    join courses on courses.slug = lesson_seed.course_slug
    join course_modules on course_modules.course_id = courses.id
                       and course_modules.title = lesson_seed.module_title
)
update lessons
set content = target_lessons.content,
    duration_minutes = target_lessons.duration_minutes,
    order_number = target_lessons.order_number,
    updated_at = now()
from target_lessons
where lessons.module_id = target_lessons.module_id
  and lessons.title = target_lessons.title;

with lesson_seed(id, course_slug, module_title, title, content, duration_minutes, order_number) as (
    values
        ('71311111-1111-4111-8111-111111111111'::uuid, 'kta-tgo', 'Формат ТГО', 'Структура ТГО в КТА', E'Цель урока: понять, из каких частей состоит тест на готовность к обучению и как распределять время.\n\nЧто сделать: выпиши блоки ТГО, отметь задания на критическое и аналитическое мышление, затем выбери порядок прохождения от простого к сложному.\n\nРезультат: ты знаешь, где быстро набрать уверенные баллы и где нельзя тратить лишние минуты.', 18, 1),
        ('71311111-1111-4111-8111-111111111112'::uuid, 'kta-tgo', 'Формат ТГО', 'Критическое мышление: как читать условие', E'Цель урока: научиться отделять факт, вывод и предположение.\n\nЧто сделать: читай условие два раза, подчеркивай опорные слова и проверяй каждый вариант ответа вопросом: следует ли это прямо из текста.\n\nРезультат: меньше ошибок из-за красивых, но неподтвержденных вариантов.', 22, 2),
        ('71311111-1111-4111-8111-111111111113'::uuid, 'kta-tgo', 'Формат ТГО', 'Аналитическое мышление: таблицы и связи', E'Цель урока: переводить текстовую задачу в таблицу, схему или короткую систему условий.\n\nЧто сделать: выпиши объекты, признаки и ограничения, затем заполняй только то, что следует из условия.\n\nРезультат: сложная задача становится набором маленьких проверяемых шагов.', 24, 3),
        ('71311111-1111-4111-8111-111111111114'::uuid, 'kta-tgo', 'Практика мышления', 'План решения задания за 90 секунд', E'Цель урока: уложиться в экзаменационный темп без паники.\n\nЧто сделать: 20 секунд на чтение, 40 секунд на решение, 20 секунд на проверку, 10 секунд на выбор ответа. Если прогресса нет, пометь вопрос и переходи дальше.\n\nРезультат: ты контролируешь время и не зависаешь на одном задании.', 16, 1),
        ('71311111-1111-4111-8111-111111111115'::uuid, 'kta-tgo', 'Практика мышления', 'Типовые ошибки в ТГО', E'Цель урока: увидеть повторяющиеся ловушки.\n\nЧто сделать: после каждой тренировки записывай ошибку в одну из групп: невнимательное чтение, лишнее предположение, неверная схема, ошибка счета, нехватка времени.\n\nРезультат: подготовка становится точной, потому что ты исправляешь причину, а не просто решаешь больше заданий.', 20, 2),
        ('71311111-1111-4111-8111-111111111116'::uuid, 'kta-tgo', 'Практика мышления', 'Мини-тренировка: выводы и допущения', E'Цель урока: закрепить критическое мышление на коротких упражнениях.\n\nЧто сделать: для каждого утверждения отметь, является ли оно фактом из условия, возможным выводом или лишним допущением. Правильный ответ должен опираться только на текст.\n\nРезультат: ты быстрее отсекаешь варианты, которые звучат правдоподобно, но не доказаны.', 20, 3),
        ('71311111-1111-4111-8111-111111111117'::uuid, 'kta-logika', 'Основы', 'Структура логического блока', E'Цель урока: понять основные типы логических заданий в подготовке к КТА.\n\nЧто сделать: раздели задания на последовательности, выводы, условия, таблицы и задачи на соответствие. Для каждого типа держи отдельный способ решения.\n\nРезультат: ты не решаешь все задания одним способом и быстрее выбираешь рабочий алгоритм.', 18, 1),
        ('71311111-1111-4111-8111-111111111118'::uuid, 'kta-logika', 'Основы', 'Числовые последовательности', E'Цель урока: находить закономерность без перебора всех вариантов.\n\nЧто сделать: проверь разность, множитель, чередование двух рядов, квадрат или куб числа, затем сравни правило на нескольких соседних элементах.\n\nРезультат: ответ выбирается по правилу, а не по догадке.', 24, 2),
        ('71311111-1111-4111-8111-111111111119'::uuid, 'kta-logika', 'Основы', 'Аргументы и выводы', E'Цель урока: отличать правильный вывод от похожего по смыслу варианта.\n\nЧто сделать: сократи условие до двух-трех посылок и проверь, добавляет ли вариант ответа новую информацию. Если добавляет, это не строгий вывод.\n\nРезультат: меньше ошибок в заданиях, где варианты специально похожи друг на друга.', 26, 3),
        ('71311111-1111-4111-8111-111111111120'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Диаграммы и множества', E'Цель урока: решать задачи, где объекты входят в несколько групп.\n\nЧто сделать: используй круги, таблицы или короткие обозначения. Сначала заполняй пересечения, затем только одиночные области.\n\nРезультат: условия не смешиваются, а количество вариантов становится управляемым.', 22, 1),
        ('71311111-1111-4111-8111-111111111121'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Условия с несколькими ограничениями', E'Цель урока: не терять ограничения в длинной задаче.\n\nЧто сделать: каждое условие запиши отдельной строкой, затем вычеркивай невозможные варианты. Не держи все связи в голове.\n\nРезультат: сложная логическая задача превращается в последовательное исключение лишнего.', 24, 2),
        ('71311111-1111-4111-8111-111111111122'::uuid, 'kta-logika', 'Задачи повышенной сложности', 'Проверка ответа без угадывания', E'Цель урока: быстро проверить выбранный вариант.\n\nЧто сделать: подставь ответ обратно в условие и проверь все ограничения, а не только последнее. Если одно условие ломается, ответ неверный.\n\nРезультат: ты находишь ошибки до отправки ответа.', 16, 3),
        ('71311111-1111-4111-8111-111111111123'::uuid, 'kta-english', 'Основы', 'Диагностика уровня', E'Цель урока: определить слабые темы до начала подготовки.\n\nЧто сделать: пройди короткий срез по грамматике, чтению и лексике, затем отметь темы, где ошибка повторяется два раза и чаще.\n\nРезультат: у тебя появляется личный список тем, а не абстрактная цель выучить английский.', 18, 1),
        ('71311111-1111-4111-8111-111111111124'::uuid, 'kta-english', 'Основы', 'Academic vocabulary', E'Цель урока: понимать академические слова по контексту.\n\nЧто сделать: учи не отдельные переводы, а связки слов: причина, следствие, сравнение, противопоставление, пример. В тексте ищи маркеры связи между предложениями.\n\nРезультат: незнакомое слово реже ломает понимание всего абзаца.', 22, 2),
        ('71311111-1111-4111-8111-111111111125'::uuid, 'kta-english', 'Основы', 'Reading strategies', E'Цель урока: читать текст быстрее и точнее.\n\nЧто сделать: сначала найди тему текста и позицию автора, затем переходи к вопросам на детали. Не переводи каждое слово, если смысл предложения уже понятен.\n\nРезультат: ты экономишь время на чтении и меньше путаешь похожие ответы.', 24, 3),
        ('71311111-1111-4111-8111-111111111126'::uuid, 'kta-english', 'Чтение и грамматика', 'Grammar focus: времена и модальные глаголы', E'Цель урока: закрыть частые грамматические ошибки.\n\nЧто сделать: для каждого предложения найди время, лицо, число и модальный оттенок. Только после этого выбирай форму глагола.\n\nРезультат: ответ становится логичным по грамматике, а не выбранным по звучанию.', 24, 1),
        ('71311111-1111-4111-8111-111111111127'::uuid, 'kta-english', 'Чтение и грамматика', 'Reading: main idea и details', E'Цель урока: различать вопросы на главную мысль и детали.\n\nЧто сделать: если вопрос про main idea, смотри на весь текст. Если вопрос про detail, найди конкретную строку и не обобщай лишнего.\n\nРезультат: ты не отвечаешь деталями на общий вопрос и наоборот.', 22, 2),
        ('71311111-1111-4111-8111-111111111128'::uuid, 'kta-english', 'Чтение и грамматика', 'Ошибки в вариантах ответа', E'Цель урока: видеть ловушки в английских тестах.\n\nЧто сделать: проверяй варианты на слишком широкое обобщение, противоположный смысл, слово из текста без правильной идеи и грамматически красивую, но неверную форму.\n\nРезультат: ты выбираешь ответ по смыслу текста, а не по знакомым словам.', 20, 3),
        ('71311111-1111-4111-8111-111111111129'::uuid, 'kta-profile', 'Основы', 'Диагностический разбор', E'Цель урока: начать профильную подготовку с реальной картины знаний.\n\nЧто сделать: выбери темы дисциплины, пройди стартовый срез и отметь каждую тему цветом: знаю, путаюсь, не знаю.\n\nРезультат: план подготовки строится по слабым местам, а не по случайному порядку.', 18, 1),
        ('71311111-1111-4111-8111-111111111130'::uuid, 'kta-profile', 'Основы', 'Работа с теорией', E'Цель урока: учить теорию так, чтобы она помогала решать тест.\n\nЧто сделать: после каждого определения запиши пример, контрпример и связь с соседней темой. Не оставляй теорию в виде списка фраз.\n\nРезультат: понятия легче вспоминаются в задании.', 22, 2),
        ('71311111-1111-4111-8111-111111111131'::uuid, 'kta-profile', 'Основы', 'Закрепление темы', E'Цель урока: превратить изученную тему в устойчивый навык.\n\nЧто сделать: реши 10-15 заданий по одной теме, проверь ошибки, затем через два дня вернись к тем же типам вопросов.\n\nРезультат: тема не забывается сразу после чтения конспекта.', 24, 3),
        ('71311111-1111-4111-8111-111111111132'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Как выбрать профильные дисциплины', E'Цель урока: не ошибиться с направлением подготовки.\n\nЧто сделать: сверь образовательную программу, группу направлений и перечень профильных дисциплин, затем собери список тем для каждой дисциплины.\n\nРезультат: ты готовишь именно те предметы, которые нужны для поступления.', 18, 1),
        ('71311111-1111-4111-8111-111111111133'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Конспект по темам кодификатора', E'Цель урока: сделать конспект рабочим инструментом.\n\nЧто сделать: на одну тему оставляй одну страницу: определения, формулы или правила, два примера и три частые ошибки.\n\nРезультат: перед тестом можно быстро повторить главное без перечитывания учебника.', 26, 2),
        ('71311111-1111-4111-8111-111111111134'::uuid, 'kta-profile', 'Подготовка по дисциплинам', 'Практика по слабым темам', E'Цель урока: убрать повторяющиеся ошибки.\n\nЧто сделать: сортируй ошибки по теме и причине. Если ошибка повторяется, вернись к теории, а не просто решай новые задания.\n\nРезультат: балл растет за счет точечного исправления слабых мест.', 22, 3),
        ('71311111-1111-4111-8111-111111111135'::uuid, 'kta-admission-plan', 'Поступление', 'Что такое КТА для магистратуры', E'Цель урока: понять роль комплексного тестирования при поступлении.\n\nЧто сделать: разберись, какие блоки относятся к твоему направлению, какой порог нужен и какие документы понадобятся для регистрации.\n\nРезультат: подготовка становится привязанной к поступлению, а не просто к набору тестов.', 16, 1),
        ('71311111-1111-4111-8111-111111111136'::uuid, 'kta-admission-plan', 'Поступление', 'Баллы и приоритеты подготовки', E'Цель урока: распределить усилия по блокам теста.\n\nЧто сделать: выпиши максимальные баллы по каждому разделу и отметь, где проще всего поднять результат за ближайшие две недели.\n\nРезультат: ты не тратишь одинаковое время на темы с разной отдачей.', 18, 2),
        ('71311111-1111-4111-8111-111111111137'::uuid, 'kta-admission-plan', 'Поступление', 'Регистрация и дедлайны', E'Цель урока: не потерять поступление из-за организационных ошибок.\n\nЧто сделать: заведи календарь регистрации, оплаты при необходимости, выбора пункта тестирования, даты экзамена и подачи документов.\n\nРезультат: все важные шаги видны заранее.', 14, 3),
        ('71311111-1111-4111-8111-111111111138'::uuid, 'kta-admission-plan', 'План подготовки', 'План на 30 дней', E'Цель урока: собрать короткий интенсив без хаоса.\n\nЧто сделать: 5 дней диагностики и базовой теории, 15 дней практики по темам, 7 дней пробных тестов, 3 дня легкого повторения и сна.\n\nРезультат: у тебя есть реалистичный план до экзамена.', 18, 1),
        ('71311111-1111-4111-8111-111111111139'::uuid, 'kta-admission-plan', 'План подготовки', 'План на 90 дней', E'Цель урока: выстроить спокойную подготовку на три месяца.\n\nЧто сделать: первый месяц закрывает теорию, второй месяц усиливает практику, третий месяц имитирует экзамен и исправляет ошибки.\n\nРезультат: подготовка идет без перегруза и случайных рывков.', 18, 2),
        ('71311111-1111-4111-8111-111111111140'::uuid, 'kta-admission-plan', 'План подготовки', 'Контроль прогресса', E'Цель урока: измерять реальные изменения.\n\nЧто сделать: раз в неделю фиксируй балл, время, ошибки по темам и вопросы, где ты сомневался. Смотри не только на итоговый процент, но и на причины ошибок.\n\nРезультат: ты видишь, что именно улучшилось и что еще тормозит результат.', 20, 3),
        ('71311111-1111-4111-8111-111111111141'::uuid, 'kta-practice-strategy', 'Тренировки', 'Как проходить пробный тест', E'Цель урока: сделать пробный тест похожим на настоящий экзамен.\n\nЧто сделать: поставь таймер, убери подсказки, проходи все блоки подряд и не проверяй ответы до конца попытки.\n\nРезультат: итоговый балл показывает реальную готовность, а не комфортную домашнюю практику.', 16, 1),
        ('71311111-1111-4111-8111-111111111142'::uuid, 'kta-practice-strategy', 'Тренировки', 'Экзаменационный темп', E'Цель урока: научиться двигаться по тесту без потери времени.\n\nЧто сделать: на первой проходке решай легкие вопросы, на второй возвращайся к средним, на третьей оставляй только сложные.\n\nРезультат: легкие баллы не теряются из-за одной трудной задачи.', 18, 2),
        ('71311111-1111-4111-8111-111111111143'::uuid, 'kta-practice-strategy', 'Тренировки', 'Повторение перед экзаменом', E'Цель урока: повторить главное без перегрузки.\n\nЧто сделать: за последние дни смотри только конспект ошибок, формулы, правила и задания, где раньше были сомнения.\n\nРезультат: перед экзаменом ты укрепляешь известное, а не открываешь новые тяжелые темы.', 14, 3),
        ('71311111-1111-4111-8111-111111111144'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Журнал ошибок', E'Цель урока: хранить ошибки так, чтобы они приносили пользу.\n\nЧто сделать: для каждой ошибки записывай тему, тип задания, выбранный ответ, правильную идею и причину промаха.\n\nРезультат: журнал становится картой подготовки, а не списком неудач.', 18, 1),
        ('71311111-1111-4111-8111-111111111145'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Повтор сложных вопросов', E'Цель урока: возвращать сложные задания в правильный момент.\n\nЧто сделать: повторяй ошибочные вопросы через 1 день, 3 дня и 7 дней. Если снова ошибка, вернись к теории.\n\nРезультат: слабые темы закрепляются постепенно.', 16, 2),
        ('71311111-1111-4111-8111-111111111146'::uuid, 'kta-practice-strategy', 'Разбор ошибок', 'Как понять, что тема закрыта', E'Цель урока: не обманывать себя ощущением знакомой темы.\n\nЧто сделать: тема считается закрытой, если ты решаешь новые задания правильно, укладываешься во время и можешь объяснить ход решения.\n\nРезультат: прогресс становится реальным и проверяемым.', 18, 3)
),
target_lessons as (
    select lesson_seed.*, course_modules.id as module_id
    from lesson_seed
    join courses on courses.slug = lesson_seed.course_slug
    join course_modules on course_modules.course_id = courses.id
                       and course_modules.title = lesson_seed.module_title
)
insert into lessons(id, module_id, title, video_url, content, duration_minutes, order_number, created_at, updated_at)
select id, module_id, title, null, content, duration_minutes, order_number, now(), now()
from target_lessons
where not exists (
    select 1
    from lessons existing
    where existing.module_id = target_lessons.module_id
      and existing.title = target_lessons.title
);
